mapper.select:
SELECT
    id, user_id, message_type, title, content,
    movie_id, movie_title, is_read, created_at, read_at
FROM notification_message
WHERE user_id = #{userId}

    AND is_read = #{isRead}

ORDER BY created_at DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE notification_message
SET is_read = 1,
    read_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM notification_message
WHERE id = #{id}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM notification_message
WHERE user_id = #{userId}

    AND is_read = #{isRead}
